insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Chaussures de sécurité', 'armure', 18000, '', '', 'pieds', 'Coups de pied : +1 dégât. Protègent des pièges au sol.', 'Bottines à coque d’acier, look urbain.' where not exists (select 1 from public.items where nom = 'Chaussures de sécurité');
insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Veste de motard en cuir', 'armure', 45000, '1', '', 'corps_dessus', '', 'Cuir épais et coudes renforcés. Ne détonne nulle part.' where not exists (select 1 from public.items where nom = 'Veste de motard en cuir');
insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Long manteau de cuir', 'armure', 95000, '1', '', 'corps_dessus', 'Dissimule une arme longue (épée, fusil à pompe) sous le pan.', 'Trench de cuir lourd, poches intérieures profondes.' where not exists (select 1 from public.items where nom = 'Long manteau de cuir');
insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Blouson à coques', 'armure', 80000, '2', '-5', 'corps_dessus', '', 'Blouson de moto avec protections intégrées aux épaules, coudes et dos.' where not exists (select 1 from public.items where nom = 'Blouson à coques');
insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Sweat en Kevlar', 'armure', 140000, '2', '', 'corps_dessus', 'Contre les armes contondantes et les balles : réduction 1 seulement.', 'A l’air d’un sweat à capuche ordinaire. Doublure tissée anti-coupure.' where not exists (select 1 from public.items where nom = 'Sweat en Kevlar');
insert into public.items (nom, categorie, prix, reduction, malus, emplacement, effets, description) select 'Casque de moto intégral', 'armure', 40000, '1', '', 'tete', 'Se cumule avec une armure de corps. PER −10 tant qu’il est porté (champ de vision réduit).', 'Le casque le moins suspect du monde, tant qu’on a une moto.' where not exists (select 1 from public.items where nom = 'Casque de moto intégral');

